def sha256_of(path):
    with open(path, "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()


def run(cmd, cwd=None, allow_fail=False):
    print(f"[RUN] {' '.join(cmd)} (cwd={cwd or REPO_ROOT})")
    result = subprocess.run(cmd, cwd=cwd or REPO_ROOT, shell=False,
                             capture_output=True, text=True, timeout=900)
    if result.stdout:
        print(result.stdout)
    if result.stderr:
        print(result.stderr, file=sys.stderr)
    if result.returncode != 0 and not allow_fail:
        raise RuntimeError(f"コマンド失敗 (rc={result.returncode}): {' '.join(cmd)}")
    return result.returncode


def run_capture(cmd, cwd=None, allow_fail=False):
    print(f"[RUN] {' '.join(cmd)} (cwd={cwd or REPO_ROOT})")
    result = subprocess.run(cmd, cwd=cwd or REPO_ROOT, shell=False,
                             capture_output=True, text=True, timeout=900)
    if result.returncode != 0 and not allow_fail:
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)
        raise RuntimeError(f"コマンド失敗 (rc={result.returncode}): {' '.join(cmd)}")
    return result.returncode, result.stdout, result.stderr


def git(args):
    return run(["git"] + args, cwd=REPO_ROOT)


def compose(args, cwd=None, allow_fail=False, capture=False):
    cmd = ["docker", "compose", "-p", COMPOSE_PROJECT] + args
    if capture:
        return run_capture(cmd, cwd=cwd or REPO_ROOT, allow_fail=allow_fail)
    return run(cmd, cwd=cwd or REPO_ROOT, allow_fail=allow_fail)


def main():
    print("=== Gate #7b: 不足していた型定義の追加 適用開始 ===\n")

    current_head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=REPO_ROOT).decode().strip()
    if current_head != EXPECTED_HEAD:
        print(f"[ABORT] HEAD不一致。期待={EXPECTED_HEAD} 実際={current_head}")
        sys.exit(1)
    print(f"[OK] HEAD一致確認: {current_head}")

    status = subprocess.check_output(
        ["git", "status", "--porcelain", "--untracked-files=no"], cwd=REPO_ROOT
    ).decode()
    if status.strip():
        print("[ABORT] 追跡済みファイルに未コミットの変更があります。")
        print(status)
        sys.exit(1)
    print("[OK] 作業ツリーはクリーン")

    for f in MODIFIED_FILES:
        path = os.path.join(REPO_ROOT, f)
        if not os.path.exists(path):
            print(f"[ABORT] 対象ファイルが存在しません: {f}")
            sys.exit(1)
        actual = sha256_of(path)
        if actual != PREIMAGES[f]:
            print(f"[ABORT] preimage不一致: {f}\n        期待: {PREIMAGES[f]}\n        実際: {actual}")
            sys.exit(1)
    print(f"[OK] preimage一致確認 ({len(MODIFIED_FILES)}ファイル)")

    backups = {}
    for f in MODIFIED_FILES:
        path = os.path.join(REPO_ROOT, f)
        bak = path + ".gate7b.bak"
        shutil.copy2(path, bak)
        backups[f] = bak

    try:
        for f in MODIFIED_FILES:
            path = os.path.join(REPO_ROOT, f)
            content = base64.b64decode(CONTENT_B64[f])
            with open(path, "wb") as fh:
                fh.write(content)
            print(f"[WRITE] {f} ({len(content)} bytes)")

        print("\n[GATE] TypeScriptエラー件数の確認(後退が無いことを確認) ...")
        rc, out, err = run_capture(["npx", "tsc", "--noEmit"], cwd=FRONTEND_DIR, allow_fail=True)
        error_count = out.count("error TS") + err.count("error TS")
        print(f"[INFO] 現在のTypeScriptエラー件数: {error_count} (適用前340件)")
        if error_count > 340:
            raise RuntimeError(f"エラー件数が悪化しました({error_count} > 340)。適用を中止します。")
        print("[OK] エラー件数は後退していません")

        print("\n[GATE] vite build (CIのblockingチェックと同一) ...")
        run(["npx", "vite", "build"], cwd=FRONTEND_DIR)
        print("[OK] vite build 成功")

        print("\n[GATE] frontendコンテナの再ビルド ...")
        compose(["build", "frontend"])
        compose(["up", "-d", "frontend"])
        import time as _time
        _time.sleep(5)
        rc, out, _ = compose(["ps", "--services", "--status", "running"], capture=True, allow_fail=True)
        if "frontend" not in out.split():
            raise RuntimeError("frontendコンテナの再起動後、running状態を確認できませんでした。")
        print("[OK] frontendコンテナ再ビルド・起動確認 PASS")

        print("\n[OK] 全Gate PASS。commit/pushへ進みます。")

        for f in MODIFIED_FILES:
            bak = backups[f]
            if os.path.exists(bak):
                os.remove(bak)

        git(["add"] + MODIFIED_FILES)

        commit_message = (
            "fix(frontend): add missing type definitions, fix import bugs (Gate #7b)\n"
            "\n"
            f"TypeScript errors: 340 -> {error_count} (npx tsc --noEmit).\n"
            "\n"
            "- Add 16 missing exports to src/types/index.ts (TravelPlan, ScheduleItem,\n"
            "  DaySchedule, CreatePlanData, CreateScheduleItemData, OptimizationRequest/\n"
            "  Result/Job/History, TransportMode, EventCategory, Coordinates,\n"
            "  DragDropState, DropResult, LoginCredentials, RegisterData), shaped from\n"
            "  actual usage in usePlan/useDragDrop/useOptimization/useAuth hooks\n"
            "- Fix DayView/PlanHeader/ShareModal.tsx using '../../types' (wrong depth,\n"
            "  same bug class as Gate #7a) -> '../types'\n"
            "- Fix DayView.tsx named-importing ScheduleItem component (default export\n"
            "  only) -> default import\n"
            "- Fix planStore.ts importing nonexistent 'apiService' named export from\n"
            "  services/api.ts (actual export is 'api'); verified getPlans/getPlan/\n"
            "  createPlan/updatePlan/deletePlan/searchSpots all exist on that object,\n"
            "  so this was purely an import-name bug, not a missing-method one\n"
            "\n"
            "NOT addressed here (needs a design decision, tracked as Gate #7c):\n"
            "usePlan.tsx and useOptimization.tsx call api.get()/api.post() (axios-style)\n"
            "against /travel/plans/... paths, but the real api object (CompleteTravelAPI)\n"
            "has no such generic methods, and the real backend (Gate #6) serves\n"
            "/api/v1/travel-plans/. Filling in types without resolving this would\n"
            "compile but not actually work at runtime.\n"
            "\n"
            "Verified: npx vite build succeeds; frontend container rebuilt and\n"
            "confirmed running via docker compose.\n"
            "\n"
            "出典: Claude(claude.ai)セッション 2026-09-01, TravelCanvas Gate #7b"
        )
        git(["commit", "-m", commit_message])
        print("[OK] commit完了")

        git(["push", "origin", "HEAD"])
        print("[OK] push完了")

        new_head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=REPO_ROOT).decode().strip()
        print(f"\n[DONE] Gate #7b 適用完了。新HEAD = {new_head}")

        self_path = os.path.abspath(__file__)
        if os.path.exists(self_path):
            os.remove(self_path)
            print(f"[CLEANUP] パッチ自身を削除しました: {self_path}")
        return

    except Exception as exc:
        print(f"\n[FAILURE] {exc}")
        print("[ROLLBACK] 変更対象ファイルのみをSHA-256一致までrestoreします。")
        for f in MODIFIED_FILES:
            path = os.path.join(REPO_ROOT, f)
            bak = backups.get(f)
            if bak and os.path.exists(bak):
                shutil.copy2(bak, path)
                os.remove(bak)
                restored_hash = sha256_of(path)
                match = "OK" if restored_hash == PREIMAGES[f] else "MISMATCH"
                print(f"  restore {f}: {match}")
        print("[ROLLBACK] 完了。commit/pushは実行されていません。")
        sys.exit(1)


if __name__ == "__main__":
    main()
